import { NextResponse } from "next/server";
import path from "path";
import fs from "fs";
import ejs from "ejs";
import puppeteer from "puppeteer";

export async function POST(req: Request) {
  try {
    let body: any = null;

    try {
      body = await req.json();
    } catch {
      body = null;
    }

    let parsed: any;

    // 🟢 Worker / direct data
    if (body && (body.data || body.report)) {
      parsed = body.data || body;
    } else {
      // 🟢 Direct API call to /api/pdf-data
      const baseUrl = process.env.APP_URL || "http://localhost:3000";
      const res = await fetch(`${baseUrl}/api/pdf-data`, {
        method: "POST",
        cache: "no-store",
      });

      if (!res.ok) {
        return NextResponse.json(
          { message: "Failed to fetch report data" },
          { status: 500 }
        );
      }

      const json = await res.json();
      parsed = json?.data;
    }

    // core object as before
    const core = parsed?.data?.data || {};

    const callRecords: any[] = Array.isArray(core.calls) ? core.calls : [];
    const smsRecords: any[] = Array.isArray(core.sms) ? core.sms : [];

    console.log(
      "DEBUG calls length:",
      Array.isArray(core.calls) ? core.calls.length : "no array"
    );
    console.log(
      "DEBUG sms length:",
      Array.isArray(core.sms) ? core.sms.length : "no array"
    );

    const templatePath = path.join(process.cwd(), "src", "views", "report.ejs");
    const outputDir = path.join(process.cwd(), "generated");
    fs.mkdirSync(outputDir, { recursive: true });

    const target = core.target || {};
    const reportMetadata = core.reportMetadata || {};

    // ---------- FULL PAYLOAD FOR SINGLE BIG PDF ----------
    const payload = {
      title: "Intelligence Report",
      targetInfo: {
        code: target.targetCode || "N/A",
        number: target.targetNumber || "Unknown",
        name: target.fullName || "N/A",
        aliases: target.aliases?.join(", ") || "None",
        categories: target.categories?.join(", ") || "N/A",
        status: target.status || "N/A",
      },
      stats: {
        totalCalls: callRecords.length,
        totalSMS: smsRecords.length,
        fileCount: reportMetadata.fileCount || "N/A",
        highPriorityCalls:
          callRecords.filter((c) => c?.criticality?.[0]?.value === "HIGH")
            .length || 0,
        generatedAt: Date.now(),
      },
      // Summary sections (same as pehle)
      topCallsSummaries: core.topCallsSummaries || [],
      entities: core.entities || {
        persons: [],
        locations: [],
        organizations: [],
      },
      keywordsSummary: core.keywordsSummary || {
        targetKeywords: [],
        globalKeywords: [],
      },
      // FULL CALLS TABLE (no chunking here)
      callRecordsDetailedTable: {
        headers: [
          "DateTime",
          "Duration",
          "Caller",
          "Callee",
          "Type",
          "Category",
          "Criticality",
          "Status",
          "Language",
          "Location",
          "File",
        ],
        rows: callRecords.map((c) => [
          c.callDatetime || "N/A",
          `${c.duration || 0}s`,
          c.callerNumber || "N/A",
          c.calleeNumber || "N/A",
          c.callType || "N/A",
          c.category || "N/A",
          c.criticality?.[0]?.value || "N/A",
          c.status || "N/A",
          c.language || "N/A",
          c.location || "N/A",
          c.fileName || "N/A",
        ]),
      },
      // (If later you want SMS table in same PDF, can add here)
      smsRecordsDetailedTable: {
        headers: [],
        rows: [],
      },
    };

    console.log(
      "API payload rows (calls):",
      payload.callRecordsDetailedTable.rows.length
    );

    const html = await ejs.renderFile(templatePath, { payload });

    const finalPath = path.join(
      outputDir,
      `intelligence-report-full-${Date.now()}.pdf`
    );

    const browser = await puppeteer.launch({
      headless: true,
      args: ["--no-sandbox"],
    });

    const page = await browser.newPage();
    await page.emulateMediaType("screen");
    await page.setContent(html, {
      waitUntil: ["domcontentloaded", "networkidle0"],
    });

    await page.pdf({
  path: finalPath,
  format: "A4",
  printBackground: true,
  margin: {
    top: "10mm",
    right: "10mm",
    bottom: "10mm",
    left: "10mm",
  },
  scale: 0.9,
  preferCSSPageSize: true,
});

    await browser.close();

    return NextResponse.json(
      { message: "Full PDF ready!", path: finalPath },
      { status: 200 }
    );
  } catch (err) {
    console.error("PDF generation error:", err);
    return NextResponse.json(
      { message: "Internal Server Error" },
      { status: 500 }
    );
  }
}
